// Shown on a first visit. Clinical terms to ICD-10 is the case string similarity
// cannot solve, so the opening screen shows what the models are for.
export const DEFAULT_EXAMPLE = "icd10";

/** Every example, in picker order. */
export const EXAMPLE_LIST = Object.entries(EXAMPLES)
  .map(([key, e]) => ({ key, ...e }));

/**
 * Which example these two lists are, or null once the user has edited them.
 *
 * Derived, not tracked: as a flag it needed clearing in every
 * handler that touched a list, so the next one added would have left the notice
 * claiming the user's own data was an example.
 */
export function matchExample(messy, reference) {
  const hit = EXAMPLE_LIST.find(
    (e) => e.messy === messy && e.reference === reference,
  );
  return hit ? hit.key : null;
}
